WITH prometheus_query_step_1 AS (SELECT timeSeriesIdToGroup(id) AS group, arrayFilter(lambda(tuple(sample), not(equals(reinterpretAsUInt64(tupleElement(sample, 2)), 9218868437227405314))), samples) AS samples FROM timeSeriesSelector('default', 'ts', 'metric_0', toDateTime64(toDecimal128('1793505300.001', 3), 3), toDateTime64(toDecimal128('1793505600', 3), 3), 'samples')), prometheus_query_step_2 AS (SELECT group, timeSeriesRateToGrid(toDateTime64(toDecimal128('1793505600', 3), 3), toDateTime64(toDecimal128('1793505600', 3), 3), toDecimal64('0', 3), toDecimal64('300', 3))(samples) AS `values` FROM prometheus_query_step_1 GROUP BY group), prometheus_query_step_3 AS (SELECT timeSeriesRemoveTag(group, '__name__') AS new_group, `values` FROM prometheus_query_step_2), prometheus_query_step_4 AS (SELECT new_group AS group, `values` FROM prometheus_query_step_3), prometheus_query_step_5 AS (SELECT timeSeriesRemoveAllTagsExcept(group, ['cluster', 'job']) AS new_group, sumForEach(`values`) AS `values` FROM prometheus_query_step_4 GROUP BY new_group), prometheus_query_step_6 AS (SELECT new_group AS group, `values` FROM prometheus_query_step_5 WHERE notEmpty(`values`)) SELECT timeSeriesGroupToTags(group) AS tags, toDateTime64(toDecimal128('1793505600', 3), 3) AS timestamp, toFloat64(assumeNotNull(arrayElement(`values`, 1))) AS value FROM prometheus_query_step_6 WHERE isNotNull(arrayElement(`values`, 1)) ORDER BY tags ASC
